# Retry extracting text using pdfplumber with a more optimized approach
import pdfplumber

extracted_insights = []

try:
    with pdfplumber.open(transcript_path) as pdf:
        for page in pdf.pages:
            text = page.extract_text()
            if text:
                # Search for key concepts in the extracted text
                if any(keyword in text.lower() for keyword in key_concepts):
                    extracted_insights.append(text)
except Exception as e:
    extracted_insights.append(f"Error encountered: {e}")

# Display a sample of the extracted insights
extracted_insights[:5]

